import{_ as s}from"./chunks/architecture.Cs8uKTTN.js";import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"fr/concepts/overview.md","filePath":"fr/concepts/overview.md","lastUpdated":1784903584000}'),o={name:"fr/concepts/overview.md"};function c(p,e,r,l,d,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>swag2mcp agit comme un pont entre les spécifications API et les agents LLM :</p><img src="'+s+`" width="800" alt="Architecture swag2mcp"><h2 id="concepts-fondamentaux" tabindex="-1">Concepts fondamentaux <a class="header-anchor" href="#concepts-fondamentaux" aria-label="Permalink to &quot;Concepts fondamentaux&quot;">​</a></h2><p><strong>Spec</strong> — un conteneur logique représentant un domaine ou service API (par exemple, YouTube, Binance, Open-Meteo). Chaque spec a un <code>domain</code> unique, une <code>base_url</code>, une <code>auth</code> optionnelle, et contient une ou plusieurs collections. Vous pouvez également définir <code>llm_instruction</code> — un indice court injecté dans l&#39;invite système swag2mcp qui indique au LLM à quoi sert cette spec et quand l&#39;utiliser. En savoir plus : <a href="./specs">Specs</a>.</p><p><strong>Collection</strong> — un fichier OpenAPI/Swagger/Postman unique décrivant une API spécifique. Elle pointe vers un <code>location</code> (URL ou chemin de fichier local). Une spec peut avoir plusieurs collections — par exemple, la spec « meteo » pourrait avoir les collections « Prévisions », « Qualité de l&#39;air » et « Maritime », chacune pointant vers un fichier de spécification différent. En savoir plus : <a href="./collections">Collections</a>.</p><p><strong>Étiquette (Tag)</strong> — une catégorie de points d&#39;accès dans une collection. Aide le LLM à trouver les bonnes opérations plus précisément. En savoir plus : <a href="./tags">Étiquettes</a>.</p><p><strong>Point d&#39;accès (Endpoint)</strong> — une méthode HTTP + chemin spécifique (par exemple, <code>GET /api/users</code>). Le LLM peut trouver un point d&#39;accès par description, inspecter ses paramètres et schémas, puis l&#39;invoquer. En savoir plus : <a href="./endpoints">Points d&#39;accès</a>.</p><p><strong>Espace de travail (Workspace)</strong> — le répertoire où swag2mcp stocke la configuration, le cache des specs, les réponses sauvegardées et les scripts d&#39;authentification. En savoir plus : <a href="./workspace">Espace de travail</a>.</p><h2 id="comment-cela-fonctionne" tabindex="-1">Comment cela fonctionne <a class="header-anchor" href="#comment-cela-fonctionne" aria-label="Permalink to &quot;Comment cela fonctionne&quot;">​</a></h2><ol><li><p><strong>Ajoutez une spec ou une collection</strong> — définissez-la dans la configuration YAML (<code>~/.swag2mcp/swag2mcp.yaml</code>). Par exemple :</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">API Dad Joke</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Blagues</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp analyse chaque collection</strong> — crée des étiquettes et des points d&#39;accès, les indexe pour la recherche.</p></li><li><p><strong>Le LLM trouve le bon point d&#39;accès</strong> — via les outils MCP (<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>), le LLM recherche un point d&#39;accès correspondant par description, examine ses paramètres et son schéma de requête.</p></li><li><p><strong>Le LLM invoque le point d&#39;accès</strong> — via l&#39;outil MCP <code>invoke</code>, le LLM envoie la requête. swag2mcp valide chaque paramètre d&#39;entrée par rapport au schéma OpenAPI du point d&#39;accès (paramètres de chemin, paramètres de requête, en-têtes, corps de la requête) avant d&#39;effectuer l&#39;appel. Si quelque chose ne correspond pas au schéma, le LLM reçoit une erreur claire expliquant ce qui ne va pas. Une fois validé, swag2mcp exécute l&#39;appel HTTP réel et retourne le résultat.</p></li><li><p><strong>Le résultat retourne au LLM</strong> — la réponse API est transmise à l&#39;agent. Les grandes réponses sont sauvegardées dans l&#39;espace de travail et peuvent être explorées avec trois outils MCP dédiés : <code>response_outline</code> (voir la structure), <code>response_compress</code> (réduire à un échantillon représentatif) et <code>response_slice</code> (extraire des fragments spécifiques).</p></li></ol><p>swag2mcp est un pont entre les LLM et le monde des API. Vous ajoutez des spécifications API, et le LLM — via le protocole MCP — trouve les bons points d&#39;accès, inspecte leur documentation et les appelle. Tout ce que vous avez à faire est d&#39;ajouter une spec et de démarrer le serveur MCP.</p><blockquote><p><strong>La configuration est modifiable à tout moment.</strong> Le fichier de configuration YAML (<code>~/.swag2mcp/swag2mcp.yaml</code>) peut être modifié à la main — ajoutez des specs, changez l&#39;authentification, ajustez les paramètres. Après chaque modification, redémarrez le serveur MCP (<code>swag2mcp mcp</code>) pour que les changements prennent effet.</p></blockquote><h2 id="hierarchie" tabindex="-1">Hiérarchie <a class="header-anchor" href="#hierarchie" aria-label="Permalink to &quot;Hiérarchie&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domaine, par ex. « meteo »)</span></span>
<span class="line"><span>  └── Collection 1 (fichier de spec, par ex. forecast.yml)</span></span>
<span class="line"><span>        └── Étiquette 1 (catégorie)</span></span>
<span class="line"><span>              └── Point d&#39;accès (GET /api/forecast)</span></span>
<span class="line"><span>              └── Point d&#39;accès (POST /api/forecast)</span></span>
<span class="line"><span>        └── Étiquette 2</span></span>
<span class="line"><span>              └── Point d&#39;accès (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (fichier de spec, par ex. air-quality.yml)</span></span>
<span class="line"><span>        └── Étiquette 3</span></span>
<span class="line"><span>              └── Point d&#39;accès (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const k=a(o,[["render",c]]);export{g as __pageData,k as default};
